package org.apache.commons.cli;

import org.junit.Test;
import static org.junit.Assert.*;

public class AlreadySelectedExceptionTest {

    @Test
    public void testConstructorWithOptionGroupAndOption() {
        OptionGroup optionGroup = new OptionGroup();
        Option option = new Option("x", "description");
        AlreadySelectedException exception = new AlreadySelectedException(optionGroup, option);

        assertEquals("The option 'x' was specified but an option from this group has already been selected: ''",
                     exception.getMessage());
        assertEquals(option, exception.getOption());
        assertEquals(optionGroup, exception.getOptionGroup());
    }

    @Test
    public void testConstructorWithMessage() {
        String message = "Test message";
        AlreadySelectedException exception = new AlreadySelectedException(message);

        assertEquals(message, exception.getMessage());
        assertNull(exception.getOption());
        assertNull(exception.getOptionGroup());
    }

    @Test
    public void testGetters() {
        OptionGroup optionGroup = new OptionGroup();
        Option option = new Option("y", "description");
        AlreadySelectedException exception = new AlreadySelectedException(optionGroup, option);

        assertEquals(option, exception.getOption());
        assertEquals(optionGroup, exception.getOptionGroup());
    }

    @Test
    public void testConstructorWithNulls() {
        AlreadySelectedException exception = new AlreadySelectedException("Test message", null, null);

        assertEquals("Test message", exception.getMessage());
        assertNull(exception.getOption());
        assertNull(exception.getOptionGroup());
    }
}
```

