        final String actual = Util.stripLeadingHyphens(optionName);

        if (actual != null) {

            return options.stream()

                    .filter(opt -> actual.equals(opt.getOpt()) || actual.equals(opt.getLongOpt()))

                    .findFirst().orElse(null);

