    private String getLongPrefix(final String token) {

        final String t = Util.stripLeadingHyphens(token);

        int i;

        String opt = null;

        for (i = t.length() - 2; i > 1; i--) {

            final String prefix = t.substring(0, i);

            if (options.hasLongOption(prefix)) {

                opt = prefix;

                break;

