            final String opt = token.substring(0, pos);

            final String value = token.substring(pos + 1);



            if (opt.length() == 1) {

                // -S=V

                final Option option = options.getOption(opt);

                if (option != null && option.acceptsArg()) {

                    handleOption(option);

                    currentOption.processValue(value);

                    currentOption = null;

                } else {

