            final String arg = arguments[i];

            if (arg != null) {

                if (OptionFormatter.DEFAULT_LONG_OPT_PREFIX.equals(arg)) {

                    eatTheRest = true;

                    tokens.add(OptionFormatter.DEFAULT_LONG_OPT_PREFIX);

                } else if (OptionFormatter.DEFAULT_OPT_PREFIX.equals(arg)) {

