                if (!firstLine) {

                    appendable.append(getNewLine());

                } else {

                    firstLine = false;

                }

                appendWrappedText(appendable, width, nextLineTabStop, line);

            }

        } catch (final IOException e) { // NOPMD

            // cannot happen

        }

        return appendable;

    }



