     * @return The String of without the trailing padding

     */

    protected String rtrim(final String s) {

        if (Util.isEmpty(s)) {

            return s;

        }

        int pos = s.length();

        while (pos > 0 && Character.isWhitespace(s.charAt(pos - 1))) {

            --pos;

        }

        return s.substring(0, pos);

    }



