        Options options = new Options();
        options.addOption(Option.builder("f").longOpt("file").desc("Input file").hasArg().argName("FILE").get());
        options.addOption(Option.builder("h").longOpt("help").desc("Print help").get());

        StringWriter stringWriter = new StringWriter();
        PrintWriter printWriter = new PrintWriter(stringWriter);

        HelpFormatter formatter = new HelpFormatter();
        formatter.printWriter = printWriter;
        formatter.printHelp("myapp", options);

        String output = stringWriter.toString();
        assertTrue(output.contains("usage: myapp"));
        assertTrue(output.contains("-f,--file <FILE>   Input file"));
        assertTrue(output.contains("-h,--help        Print help"));
    }

