package org.apache.commons.cli;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class MissingOptionExceptionTest {

    @Test
    public void testConstructorWithMessage() {
        String message = "Test message";
        MissingOptionException exception = new MissingOptionException(message);
        assertEquals(message, exception.getMessage());
    }

    @Test
    public void testConstructorWithSingleOption() {
        List<String> missingOptions = Collections.singletonList("-a");
        MissingOptionException exception = new MissingOptionException(missingOptions);
        assertEquals("Missing required option: -a", exception.getMessage());
        assertEquals(missingOptions, exception.getMissingOptions());
    }

    @Test
    public void testConstructorWithMultipleOptions() {
        List<String> missingOptions = Arrays.asList("-a", "-b", "-c");
        MissingOptionException exception = new MissingOptionException(missingOptions);
        assertEquals("Missing required options: -a, -b, -c", exception.getMessage());
        assertEquals(missingOptions, exception.getMissingOptions());
    }

    @Test
    public void testConstructorWithOptionGroup() {
        OptionGroup group = new OptionGroup();
        group.addOption(new Option("a", "option a"));
        group.addOption(new Option("b", "option b"));
        List<OptionGroup> missingOptions = Collections.singletonList(group);
        MissingOptionException exception = new MissingOptionException(missingOptions);
        assertEquals("Missing required option: [ -a option a, -b option b ]", exception.getMessage());
        assertEquals(missingOptions, exception.getMissingOptions());
    }

    @Test
    public void testGetMissingOptions() {
        List<String> missingOptions = Arrays.asList("-x", "-y");
        MissingOptionException exception = new MissingOptionException(missingOptions);
        assertEquals(missingOptions, exception.getMissingOptions());
    }

    @Test
    public void testGetMissingOptionsEmptyList() {
        List<String> missingOptions = Collections.emptyList();
        MissingOptionException exception = new MissingOptionException(missingOptions);
        assertEquals("Missing required option", exception.getMessage());
        assertEquals(missingOptions, exception.getMissingOptions());
    }
}
