        if (date == null || pos.getIndex() != s.length()) {

            final int errorIndex = pos.getErrorIndex() >= 0 ? pos.getErrorIndex() : pos.getIndex();

            throw new java.text.ParseException(String.format("Unparseable date: \"%s\"", s), errorIndex);

        }

        return date;

    };



