            try {

                opt.processValue(Util.stripLeadingAndTrailingQuotes(str));

            } catch (final RuntimeException exp) {

                iter.previous();

                break;

            }

        }

        if (opt.isValuesEmpty() && !opt.hasOptionalArg()) {

            throw new MissingArgumentException(opt);

        }

