        String message = "Test message";
        String option = "-v";
        UnrecognizedOptionException original = new UnrecognizedOptionException(message, option);

        // Test serialization/deserialization
        byte[] serialized = SerializationUtils.serialize(original);
        UnrecognizedOptionException deserialized = (UnrecognizedOptionException) SerializationUtils.deserialize(serialized);

        assertEquals(original.getMessage(), deserialized.getMessage());
        assertEquals(original.getOption(), deserialized.getOption());
    }
}
