            // append the arg name if it exists.

            if (option.hasArg()) {

                sb.append(" ").append(formatter.getArgName());

            }

            row.add(sb.toString());

            // append the "since" value if desired.

            if (showSince) {

                row.add(formatter.getSince());

            }

            // add the option description

            row.add(formatter.getDescription());

            rows.add(row);

