        OptionFormatter.Builder builder = OptionFormatter.builder()
            .setArgumentNameDelimiters("(", ")")
            .setDefaultArgName("value")
            .setOptPrefix("+")
            .setLongOptPrefix("++")
            .setOptSeparator(";")
            .setOptArgSeparator("=")
            .setOptionalDelimiters("{", "}")
            .setDeprecatedFormatFunction(OptionFormatter.SIMPLE_DEPRECATED_FORMAT);

        OptionFormatter formatter = builder.build(new Option("x", "description"));

        assertEquals("(", formatter.argNameDelimiters[0]);
        assertEquals(")", formatter.argNameDelimiters[1]);
