        // @formatter:off

        textStyleBuilder = TextStyle.builder()

            .setMaxWidth(DEFAULT_WIDTH)

            .setLeftPad(DEFAULT_LEFT_PAD)

            .setIndent(DEFAULT_INDENT);

        // @formatter:on

    }



    /**

