            (char) Character.PARAGRAPH_SEPARATOR,

            '\u000b', // VERTICAL TABULATION.

            '\u001c', // FILE SEPARATOR.

            '\u001d', // GROUP SEPARATOR.

            '\u001e', // RECORD SEPARATOR.

            '\u001f' // UNIT SEPARATOR.

