                final String line = columnQueue.poll();

                if (Util.isEmpty(line)) {

                    output.append(Util.repeatSpace(style.getMaxWidth() + style.getLeftPad()));

                } else {

                    output.append(line);

                }

                moreData |= !columnQueue.isEmpty();

            }

            output.append(System.lineSeparator());

        }

    }
