                }

                rest = Util.repeatSpace(restLen);

            }



            if (alignment == Alignment.LEFT) {

                sb.append(indentPad).append(text).append(rest);

            } else {

                sb.append(indentPad).append(rest).append(text);

            }

            break;

        }

        return sb.toString();

    }



